using EmployeeMonitoringAPI.Data;
using EmployeeMonitoringAPI.DTOs;
using EmployeeMonitoringAPI.Interfaces;
using EmployeeMonitoringAPI.Models;
using EmployeeMonitoringAPI.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
namespace EmployeeMonitoringAPI.Controllers;
[Route("api/[controller]")][ApiController][Authorize]
public sealed class CalendarController:ControllerBase
{
 private readonly ApplicationDbContext _db;private readonly IAuditService _audit;public CalendarController(ApplicationDbContext db,IAuditService audit){_db=db;_audit=audit;}
 [HttpGet("approved-leaves")][Authorize(Roles="Employee,Manager,HR")]
 public async Task<IActionResult> ApprovedLeaves()=>Ok(await _db.Leaves.AsNoTracking().Where(x=>x.Status=="Approved").Select(x=>new{x.LeaveId,EmployeeName=x.User!.FullName,x.FromDate,x.ToDate,x.LeaveType,Type="Leave",Title=x.LeaveType}).ToListAsync());
 [HttpGet("holidays")]
 public async Task<IActionResult> Holidays(bool includeInactive=false)=>Ok(await _db.CompanyHolidays.AsNoTracking().Where(x=>includeInactive||x.IsActive).OrderBy(x=>x.HolidayDate).ToListAsync());
 [HttpPost("holiday")][Authorize(Roles="Admin")]
 public async Task<IActionResult> AddHoliday(HolidayRequest dto){var date=dto.HolidayDate.Date;if(await _db.CompanyHolidays.AnyAsync(x=>x.HolidayDate==date&&x.IsActive))return Conflict(new{message="An active holiday already exists on this date"});var item=new CompanyHoliday{HolidayName=dto.HolidayName.Trim(),HolidayDate=date,Description=dto.Description?.Trim(),IsActive=true,CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow};_db.CompanyHolidays.Add(item);await NotifyAll("Holiday Created",$"{item.HolidayName} on {date:dd MMM yyyy}","Holiday","/admin/calendars");await _db.SaveChangesAsync();await _audit.RecordAsync("HolidayCreated","CompanyHoliday",item.HolidayId.ToString(),safeMetadata:new{item.HolidayName,item.HolidayDate});return Ok(new{message="Holiday created",item.HolidayId});}
 [HttpPut("holiday/{id:int}")][Authorize(Roles="Admin")]
 public async Task<IActionResult> UpdateHoliday(int id,HolidayRequest dto){var item=await _db.CompanyHolidays.FindAsync(id);if(item is null)return NotFound(new{message="Holiday not found"});var date=dto.HolidayDate.Date;if(await _db.CompanyHolidays.AnyAsync(x=>x.HolidayId!=id&&x.HolidayDate==date&&x.IsActive))return Conflict(new{message="An active holiday already exists on this date"});item.HolidayName=dto.HolidayName.Trim();item.HolidayDate=date;item.Description=dto.Description?.Trim();item.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();await _audit.RecordAsync("HolidayUpdated","CompanyHoliday",id.ToString());return Ok(new{message="Holiday updated"});}
 [HttpPatch("holiday/{id:int}/status")][Authorize(Roles="Admin")]
 public async Task<IActionResult> HolidayStatus(int id,StatusRequest dto){var item=await _db.CompanyHolidays.FindAsync(id);if(item is null)return NotFound(new{message="Holiday not found"});if(dto.IsActive&&await _db.CompanyHolidays.AnyAsync(x=>x.HolidayId!=id&&x.HolidayDate==item.HolidayDate&&x.IsActive))return Conflict(new{message="Another active holiday exists on this date"});item.IsActive=dto.IsActive;item.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();await _audit.RecordAsync(dto.IsActive?"HolidayReactivated":"HolidayCancelled","CompanyHoliday",id.ToString());return Ok(new{message=dto.IsActive?"Holiday reactivated":"Holiday cancelled"});}
 [HttpPost("events")][Authorize(Roles="Admin,HR,Manager")]
 public async Task<IActionResult> CreateEvent(CreateCalendarEventDto dto)
 {
  var validation=await ValidateEvent(dto);if(validation is not null)return validation;var creator=CurrentUserId();var ids=dto.UserIds.Distinct().ToList();
  if(ids.Count!=dto.UserIds.Count)return Conflict(new{message="Duplicate attendees are not allowed"});if(ids.Contains(creator))return BadRequest(new{message="The organizer must not also be listed as a participant"});
  var users=await _db.Users.Where(x=>ids.Contains(x.UserId)&&x.IsActive).ToListAsync();if(users.Count!=ids.Count)return BadRequest(new{message="All attendees must be valid active users"});
  if(User.IsInRole("Admin")&&users.Any(x=>x.Role!="Manager"))return BadRequest(new{message="Admin meetings may include active Managers only"});if(User.IsInRole("Manager")&&!await ManagerAttendeesAllowed(ids,dto.ProjectId,dto.EventType))return StatusCode(StatusCodes.Status403Forbidden,new{message="Managers may invite only direct or managed-project Employees, Admin, and authorized HR contacts"});
  var start=dto.StartTime.ToUniversalTime();var end=dto.EndTime.ToUniversalTime();var policy=await MeetingPolicy.ValidateAsync(_db,creator,dto.Title,start,end,ids);if(policy is not null)return StatusCode(policy.StatusCode,new{message=policy.Message});
  var group=Guid.NewGuid().ToString("N");foreach(var user in users){_db.CalendarEvents.Add(new CalendarEvent{Title=dto.Title.Trim(),Description=dto.Description?.Trim(),EventType=dto.EventType,StartTime=start,EndTime=end,Location=dto.Location?.Trim(),ProjectId=dto.ProjectId,Status="Scheduled",MeetingGroupId=group,UserId=user.UserId,CreatedById=creator,CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow});_db.Notifications.Add(new Notification{UserId=user.UserId,Title="Meeting Scheduled",Message=$"{dto.Title.Trim()} scheduled for {dto.StartTime:u}.",Type="Meeting",RelatedUrl="/employee/calendar",DeduplicationKey=$"meeting:{group}:{user.UserId}:created",CreatedAt=DateTime.UtcNow});}
  await _db.SaveChangesAsync();await _audit.RecordAsync("MeetingCreated","CalendarEvent",group,safeMetadata:new{dto.Title,Attendees=ids.Count,dto.ProjectId});return Ok(new{message="Meeting scheduled",meetingGroupId=group,recipients=ids.Count});
 } [HttpGet("events")]
 public async Task<IActionResult> Events(bool includeCancelled=false){var id=CurrentUserId();var q=_db.CalendarEvents.AsNoTracking().Include(x=>x.User).Include(x=>x.CreatedBy).Include(x=>x.Project).AsQueryable();if(!includeCancelled)q=q.Where(x=>x.Status!="Cancelled");if(User.IsInRole("Employee"))q=q.Where(x=>x.UserId==id);else if(User.IsInRole("Manager")){var team=await _db.Users.Where(x=>x.ManagerId==id).Select(x=>x.UserId).ToListAsync();q=q.Where(x=>x.CreatedById==id||x.UserId==id||team.Contains(x.UserId));}var rows=await q.OrderBy(x=>x.StartTime).ToListAsync();return Ok(rows.GroupBy(x=>x.MeetingGroupId).Select(g=>new{eventId=g.Min(x=>x.EventId),calendarEventId=g.Min(x=>x.EventId),meetingGroupId=g.Key,title=g.First().Title,description=g.First().Description,eventType=g.First().EventType,startTime=g.First().StartTime,endTime=g.First().EndTime,location=g.First().Location,projectId=g.First().ProjectId,projectName=g.First().Project?.ProjectName,status=g.First().Status,createdById=g.First().CreatedById,organizerName=g.First().CreatedBy?.FullName,attendees=g.Select(x=>new{x.UserId,x.User!.FullName}).ToList()}));}
 [HttpPut("events/{id:int}")][Authorize(Roles="Admin,HR,Manager")]
 public async Task<IActionResult> UpdateEvent(int id,CreateCalendarEventDto dto)
 {
  var seed=await _db.CalendarEvents.FirstOrDefaultAsync(x=>x.EventId==id);if(seed is null)return NotFound(new{message="Meeting not found"});
  if(!User.IsInRole("Admin")&&seed.CreatedById!=CurrentUserId())return Forbid();if(seed.Status=="Cancelled")return Conflict(new{message="Cancelled meetings cannot be edited"});
  var validation=await ValidateEvent(dto);if(validation is not null)return validation;var ids=dto.UserIds.Distinct().ToList();if(ids.Count!=dto.UserIds.Count)return Conflict(new{message="Duplicate attendees are not allowed"});if(ids.Contains(seed.CreatedById))return BadRequest(new{message="The organizer must not also be listed as a participant"});var start=dto.StartTime.ToUniversalTime();var end=dto.EndTime.ToUniversalTime();var policy=await MeetingPolicy.ValidateAsync(_db,seed.CreatedById,dto.Title,start,end,ids,seed.MeetingGroupId);if(policy is not null)return StatusCode(policy.StatusCode,new{message=policy.Message});
  if(await _db.Users.CountAsync(x=>ids.Contains(x.UserId)&&x.IsActive)!=ids.Count)return BadRequest(new{message="All attendees must be active users"});
  if(User.IsInRole("Manager")&&!await ManagerAttendeesAllowed(ids,dto.ProjectId,dto.EventType))return StatusCode(StatusCodes.Status403Forbidden,new{message="One or more attendees are outside your permitted scope"});
  var rows=await _db.CalendarEvents.Where(x=>x.MeetingGroupId==seed.MeetingGroupId).ToListAsync();var existing=rows.ToDictionary(x=>x.UserId);_db.CalendarEvents.RemoveRange(rows.Where(x=>!ids.Contains(x.UserId)));
  foreach(var userId in ids){if(!existing.TryGetValue(userId,out var row)){row=new CalendarEvent{MeetingGroupId=seed.MeetingGroupId,UserId=userId,CreatedById=seed.CreatedById,CreatedAt=DateTime.UtcNow,Status="Scheduled"};_db.CalendarEvents.Add(row);}row.Title=dto.Title.Trim();row.Description=dto.Description?.Trim();row.EventType=dto.EventType;row.StartTime=start;row.EndTime=end;row.Location=dto.Location?.Trim();row.ProjectId=dto.ProjectId;row.UpdatedAt=DateTime.UtcNow;_db.Notifications.Add(new Notification{UserId=userId,Title="Meeting updated",Message=$"{dto.Title} was updated for {dto.StartTime:u}.",Type="MeetingUpdate",RelatedUrl="/employee/calendar",DeduplicationKey=$"meeting:{seed.MeetingGroupId}:{userId}:updated:{DateTime.UtcNow.Ticks}",CreatedAt=DateTime.UtcNow});}
  await _db.SaveChangesAsync();await _audit.RecordAsync("MeetingUpdated","CalendarEvent",seed.MeetingGroupId);return Ok(new{message="Meeting updated"});
 } [HttpPatch("events/{id:int}/status")][Authorize(Roles="Admin,HR,Manager")]
 public async Task<IActionResult> EventStatus(int id,CalendarStatusRequest dto)
 {
  var allowed=new[]{"Scheduled","Completed","Cancelled"};if(!allowed.Contains(dto.Status,StringComparer.OrdinalIgnoreCase))return BadRequest(new{message="Invalid meeting status"});var seed=await _db.CalendarEvents.FirstOrDefaultAsync(x=>x.EventId==id);if(seed is null)return NotFound(new{message="Meeting not found"});if(!User.IsInRole("Admin")&&seed.CreatedById!=CurrentUserId())return Forbid();if(seed.Status=="Cancelled")return Conflict(new{message="Cancelled meetings cannot transition again"});var rows=await _db.CalendarEvents.Where(x=>x.MeetingGroupId==seed.MeetingGroupId).ToListAsync();foreach(var x in rows){x.Status=dto.Status;x.UpdatedAt=DateTime.UtcNow;if(dto.Status.Equals("Cancelled",StringComparison.OrdinalIgnoreCase))_db.Notifications.Add(new Notification{UserId=x.UserId,Title="Meeting cancelled",Message=$"{x.Title} was cancelled by the organizer.",Type="MeetingCancellation",RelatedUrl="/employee/calendar",DeduplicationKey=$"meeting:{seed.MeetingGroupId}:{x.UserId}:cancelled",CreatedAt=DateTime.UtcNow});}await _db.SaveChangesAsync();await _audit.RecordAsync(dto.Status=="Cancelled"?"MeetingCancelled":"MeetingStatusChanged","CalendarEvent",seed.MeetingGroupId,safeMetadata:new{dto.Status});return Ok(new{message="Meeting status updated"});
 } [HttpGet("my-calendar")]
 public Task<IActionResult> MyCalendar(DateTime? from,DateTime? to)=>CalendarFor(CurrentUserId(),from,to);
 [HttpGet("employee")][Authorize(Roles="Admin,HR,Manager")]
 public async Task<IActionResult> EmployeeCalendar(int employeeId,DateTime? from,DateTime? to){if(User.IsInRole("Admin")&&!await _db.Users.AnyAsync(x=>x.UserId==employeeId&&x.Role=="Manager"))return Forbid();if(User.IsInRole("Manager")&&!await _db.Users.AnyAsync(x=>x.UserId==employeeId&&x.ManagerId==CurrentUserId()))return Forbid();return await CalendarFor(employeeId,from,to);}
 private async Task<IActionResult> CalendarFor(int userId,DateTime? from,DateTime? to){var start=(from??new DateTime(DateTime.UtcNow.Year,DateTime.UtcNow.Month,1)).Date;var end=(to??start.AddMonths(1).AddDays(-1)).Date;var events=await _db.CalendarEvents.AsNoTracking().Where(x=>x.UserId==userId&&x.Status!="Cancelled"&&x.StartTime.Date>=start&&x.StartTime.Date<=end).Select(x=>new{x.EventId,Type=x.EventType,x.Title,Date=x.StartTime,x.StartTime,x.EndTime,x.Status}).ToListAsync();return Ok(events);}
 private async Task<bool> ManagerAttendeesAllowed(List<int> ids,int? projectId,string meetingType){var managerId=CurrentUserId();if(projectId.HasValue&&!await _db.Projects.AnyAsync(x=>x.ProjectId==projectId&&x.ManagerId==managerId&&!x.IsArchived&&x.Status!="Completed"&&x.Status!="Cancelled"))return false;var manager=await _db.Users.AsNoTracking().FirstAsync(x=>x.UserId==managerId);var users=await _db.Users.AsNoTracking().Where(x=>ids.Contains(x.UserId)&&x.IsActive).ToListAsync();if(users.Count!=ids.Count)return false;foreach(var user in users){if(user.Role=="Admin"){if(!meetingType.Equals("Administrative Meeting",StringComparison.OrdinalIgnoreCase))return false;continue;}if(user.Role=="HR"){if(!meetingType.Equals("HR Discussion",StringComparison.OrdinalIgnoreCase)||manager.AssignedHrId!=user.UserId)return false;continue;}if(user.Role!="Employee")return false;var direct=user.ManagerId==managerId;if(meetingType is "Team Meeting" or "One-to-One" or "HR Discussion"){if(!direct)return false;continue;}var projectMember=projectId.HasValue&&await _db.ProjectAssignments.AnyAsync(x=>x.ProjectId==projectId&&x.UserId==user.UserId&&x.Project!.ManagerId==managerId&&!x.Project.IsArchived);if(!direct&&!projectMember)return false;}return true;} private async Task<IActionResult?> ValidateEvent(CreateCalendarEventDto dto){if(string.IsNullOrWhiteSpace(dto.Title))return BadRequest(new{message="Meeting title is required"});if(dto.EndTime<=dto.StartTime)return BadRequest(new{message="Meeting end time must be after start time"});if(dto.UserIds.Count==0)return BadRequest(new{message="At least one attendee is required"});if(dto.ProjectId.HasValue&&!await _db.Projects.AnyAsync(x=>x.ProjectId==dto.ProjectId&&!x.IsArchived))return BadRequest(new{message="Related project must be active"});return null;}
 private async Task NotifyAll(string title,string message,string type,string url){var ids=await _db.Users.Where(x=>x.IsActive).Select(x=>x.UserId).ToListAsync();_db.Notifications.AddRange(ids.Select(id=>new Notification{UserId=id,Title=title,Message=message,Type=type,RelatedUrl=url,CreatedAt=DateTime.UtcNow}));}
 private int CurrentUserId()=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
}